&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types d&#39;inquisiteur&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_dinquisiteur_0&quot; href=&quot;#Les_arch&#233;types_dinquisiteur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agent-Intra&#231;able-(Inquisiteur).html&quot; title=&quot;Agent intra&#231;able&quot;&gt;Agent intra&#231;able&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brise-Sortil&#232;ge-(Inquisiteur).html&quot; title=&quot;Brise-sortil&#232;ge&quot;&gt;Brise-sortil&#232;ge&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Foi-(Inquisiteur).html&quot; title=&quot;Chasseur de foi&quot;&gt;Chasseur de foi&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Reliques-(Inquisiteur).html&quot; title=&quot;Chasseur de reliques&quot;&gt;Chasseur de reliques&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Sorci&#232;res-(Inquisiteur).html&quot; title=&quot;Chasseur de sorci&#232;res&quot;&gt;Chasseur de sorci&#232;res&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Vampires-(Inquisiteur).html&quot; title=&quot;Chasseur de vampires&quot;&gt;Chasseur de vampires&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Vigilant-(Inquisiteur).html&quot; title=&quot;D&#233;fenseur vigilant&quot;&gt;D&#233;fenseur vigilant&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exarque-(Inquisiteur).html&quot; title=&quot;Exarque&quot;&gt;Exarque&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exorciste-(Inquisiteur).html&quot; title=&quot;Exorciste&quot;&gt;Exorciste&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Exterminateur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Exterminateur sacr&#233;&quot;&gt;Exterminateur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extracteur-(Inquisiteur).html&quot; title=&quot;Extracteur&quot;&gt;Extracteur&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Tactique-(Inquisiteur).html&quot; title=&quot;Guide tactique&quot;&gt;Guide tactique&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;r&#233;tique-(Inquisiteur).html&quot; title=&quot;H&#233;r&#233;tique&quot;&gt;H&#233;r&#233;tique&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Iconoclaste-(Inquisiteur).html&quot; title=&quot;Iconoclaste&quot;&gt;Iconoclaste&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Immolateur-(Inquisiteur).html&quot; title=&quot;Immolateur&quot;&gt;Immolateur&lt;/a&gt; (Ifrit) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Infiltrateur-(Inquisiteur).html&quot; title=&quot;Infiltrateur&quot;&gt;Infiltrateur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loup-Masqu&#233;-(Inquisiteur).html&quot; title=&quot;Loup masqu&#233;&quot;&gt;Loup masqu&#233;&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mangeur-De-P&#234;ch&#233;s-(Inquisiteur).html&quot; title=&quot;Mangeur de p&#234;ch&#233;s&quot;&gt;Mangeur de p&#234;ch&#233;s&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Chasseur-Sacr&#233;-(Inquisiteur).html&quot; title=&quot;Ma&#238;tre chasseur sacr&#233;&quot;&gt;Ma&#238;tre chasseur sacr&#233;&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Parricide-(Inquisiteur).html&quot; title=&quot;Parricide&quot;&gt;Parricide&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;Dhampir&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;cheur-(Inquisiteur).html&quot; title=&quot;Pr&#234;cheur&quot;&gt;Pr&#234;cheur&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Traqueur-Des-Ombres-(Inquisiteur).html&quot; title=&quot;Traqueur des ombres&quot;&gt;Traqueur des ombres&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de lintrigue (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Intrigue/Art de l&#39;intrigue&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUI.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;En tant que r&#244;deur de l&#39;ombre passion&#233;, un traqueur des ombres observe les ennemis de sa foi et frappe avant m&#234;me que les malheureuses victimes ne sachent qu&#39;il r&#244;de dans les parages.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un traqueur des ombres ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe, mais en retire &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;. Cela modifie les comp&#233;tences de classe de l&#39;inquisiteur.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;H&#233;ritier obscur (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;H&#233;ritier_obscur_Sur_1&quot; href=&quot;#H&#233;ritier_obscur_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un traqueur des ombres gagne le &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lobscurit&#233;.html&quot; title=&quot;Domaine de l&amp;#39;Obscurit&#233;&quot;&gt;domaine de l&#39;Obscurit&#233;&lt;/a&gt; avec le &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lobscurit&#233;.html#Sous-domaines_0&quot; title=&quot;Domaine de l&amp;#39;Obscurit&#233;&quot;&gt;sous-domaine de la Nuit&lt;/a&gt;, m&#234;me si sa divinit&#233; ne l&#39;offre normalement pas. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#DOMAINE&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;domaine&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Jugement&lt;a class=&quot;headeranchor&quot; id=&quot;Jugement_2&quot; href=&quot;#Jugement_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les traqueurs des ombres sont plus efficaces lorsqu&#39;ils prennent le dessus sur un adversaire. Un traqueur des ombres a acc&#232;s au jugement suivant.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traque.&lt;/b&gt; Le traqueur des ombres gagne un bonus de saintet&#233; de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; contre les cr&#233;atures qui ne sont pas conscientes de sa pr&#233;sence (souvent parce qu&#39;il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisible&lt;/a&gt; ou utilise la &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;). Ce bonus augmente de 2 tous les 5 niveaux d&#39;inquisiteur qu&#39;il poss&#232;de.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;Cette capacit&#233; remplace le jugement de &lt;a class=&quot;pagelink&quot; href=&quot;Jugements.html#JUSTICE&quot; title=&quot;Les jugements d&amp;#39;inquisiteur&quot;&gt;justice&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Rapide et silencieux (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Rapide_et_silencieux_Ext_3&quot; href=&quot;#Rapide_et_silencieux_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les traqueurs des ombres fondent souvent sur leurs proies avec une gr&#226;ce et une efficacit&#233; mortelles. Un traqueur des ombres gagne un bonus de moral &#224; tous ses tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son niveau d&#39;inquisiteur (minimum +1). Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#REGARDESEVERE&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;regard s&#233;v&#232;re&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Efficacit&#233; mortelle (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Efficacit&#233;_mortelle_Ext_4&quot; href=&quot;#Efficacit&#233;_mortelle_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 14, un traqueur des ombres devient encore plus mortel contre les ennemis qui ne l&#39;ont pas encore remarqu&#233; dans l&#39;ombre. Chaque fois qu&#39;il confirme un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; contre un ennemi qui n&#39;est pas conscient de sa pr&#233;sence, il ignore toute &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;r&#233;duction de d&#233;g&#226;ts&lt;/a&gt; que la cible pourrait avoir et ajoute son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jet de d&#233;g&#226;ts&lt;/a&gt; (qui est multipli&#233; sur le coup critique comme &#224; l&#39;accoutum&#233;e) ; de plus, si la cible a une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;g&#233;n&#233;ration-(Capacit&#233;).html&quot; title=&quot;R&#233;g&#233;n&#233;ration (Ext)&quot;&gt;r&#233;g&#233;n&#233;ration&lt;/a&gt;, la cr&#233;ature perd sa r&#233;g&#233;n&#233;ration pendant le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; suivant le coup critique et peut mourir normalement pendant ce round. Les cr&#233;atures dont la r&#233;g&#233;n&#233;ration fonctionne constamment sont immunis&#233;es contre cette capacit&#233;.&lt;br /&gt;&lt;br /&gt;Enfin, si le traqueur des ombres inflige des d&#233;g&#226;ts d&#39;&#233;nergie &#224; une cr&#233;ature ignorant sa pr&#233;sence et vuln&#233;rable &#224; ce type d&#39;&#233;nergie, elle inflige 2 points de d&#233;g&#226;ts suppl&#233;mentaires par d&#233; lanc&#233;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#EXPLOITERLESFAIBLESSES&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;exploiter les faiblesses&lt;/a&gt;.
